import{_ as a,o,c as t,a2 as r}from"./chunks/framework.Dg5fKO7V.js";const u=JSON.parse('{"title":"Build Notes","description":"","frontmatter":{},"headers":[],"relativePath":"Build-Notes.md","filePath":"Build-Notes.md","lastUpdated":1788563284000}'),i={name:"Build-Notes.md"};function s(n,e,d,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="build-notes" tabindex="-1">Build Notes <a class="header-anchor" href="#build-notes" aria-label="Permalink to &quot;Build Notes&quot;">​</a></h1><p>Details that are surprising enough to cost someone an afternoon.</p><h2 id="node-version" tabindex="-1">Node version <a class="header-anchor" href="#node-version" aria-label="Permalink to &quot;Node version&quot;">​</a></h2><p>Node 20 or newer is supported. The lockfile no longer needs direct <code>@emnapi</code> dependencies.</p><h2 id="the-release-profile" tabindex="-1">The release profile <a class="header-anchor" href="#the-release-profile" aria-label="Permalink to &quot;The release profile&quot;">​</a></h2><p><code>Cargo.toml</code> sets <code>panic = &quot;abort&quot;</code>, <code>lto = true</code>, <code>codegen-units = 1</code>, <code>opt-level = &quot;s&quot;</code> and <code>strip = true</code>. That is what keeps the binary small, at the cost of a slow release build. Debug builds are unaffected.</p><h2 id="window-background-colour" tabindex="-1">Window background colour <a class="header-anchor" href="#window-background-colour" aria-label="Permalink to &quot;Window background colour&quot;">​</a></h2><p><code>tauri.conf.json</code> sets <code>backgroundColor</code> to the application&#39;s own dark shade. Without it the window paints white for a frame before the interface loads, which reads as a flash on every launch.</p><p>The window also starts with <code>visible: false</code> and is shown once the interface is ready, for the same reason.</p><h2 id="the-appimage-is-repacked" tabindex="-1">The AppImage is repacked <a class="header-anchor" href="#the-appimage-is-repacked" aria-label="Permalink to &quot;The AppImage is repacked&quot;">​</a></h2><p>The stock Tauri bundler copies WebKitGTK and its dependencies into the AppImage. Every supported Linux installation already provides that stack, so <code>scripts/tauri-build.mjs</code> asks <code>ldd</code> for the complete system WebKit dependency closure, excludes exactly those libraries and repacks the image.</p><p>The script logs the size before and after. It keeps the original as <code>.orig</code> until repacking has succeeded, restores it on failure and removes it only after the replacement is usable.</p><h2 id="compile-time-values" tabindex="-1">Compile-time values <a class="header-anchor" href="#compile-time-values" aria-label="Permalink to &quot;Compile-time values&quot;">​</a></h2><p><code>ANISPHERE_ANILIST_CLIENT_ID</code>, <code>ANISPHERE_DISCORD_APP_ID</code> and <code>ANISPHERE_DISCORD_IMAGE</code> are read at compile time and baked in. Changing one means rebuilding.</p><p>All three are public values. The AniList login runs on the implicit grant, which is the flow for clients that cannot hold a secret, so there is no secret to bake in.</p><p>The updater values are read at bundle time instead, so they only matter when producing installers.</p><p>A build with none of them set works. AniList login, Discord presence and auto-update simply stay off.</p><h2 id="three-files-carry-the-version" tabindex="-1">Three files carry the version <a class="header-anchor" href="#three-files-carry-the-version" aria-label="Permalink to &quot;Three files carry the version&quot;">​</a></h2><p><code>package.json</code>, <code>src-tauri/Cargo.toml</code> and <code>src-tauri/tauri.conf.json</code>. The release workflow refuses a tag that disagrees with any of them, because the bundler reads <code>tauri.conf.json</code> and a mismatch there ships installers whose version disagrees with the tag, which then breaks the updater&#39;s comparison.</p><p>Bumping the version also means regenerating <code>Cargo.lock</code>, which <code>cargo check</code> does.</p><h2 id="bundle-size-warning" tabindex="-1">Bundle size warning <a class="header-anchor" href="#bundle-size-warning" aria-label="Permalink to &quot;Bundle size warning&quot;">​</a></h2><p>The frontend build warns that a chunk is over 500 kB. That is the globe on the connectivity board, which is a WebGL library loaded on one screen. It is a warning, not a problem.</p>',22)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
